package com.hermes.assistant

import android.content.Context
import org.json.JSONObject
import java.io.File

/**
 * Versioned app-private HTML/CSS/JS storage. Bundled assets are the recovery source;
 * untrusted downloaded/prompt-generated bytes are accepted only with exact hashes.
 */
internal class UiBundleStore(context: Context) {
    private val appContext = context.applicationContext
    val rootDirectory = File(appContext.filesDir, "ui-bundles")
    private val activePointer = File(rootDirectory, "active-version.txt")
    private val previousPointer = File(rootDirectory, "previous-version.txt")

    fun seedBundledVersion(): File {
        rootDirectory.mkdirs()
        val manifestText = appContext.assets.open("ui-bundle/manifest.json")
            .bufferedReader(Charsets.UTF_8).use { it.readText() }
        val manifest = JSONObject(manifestText)
        val version = manifest.optString("version")
        require(isValidVersion(version)) { "Bundled UI version is invalid" }
        val expected = manifest.optJSONObject("files") ?: error("Bundled UI manifest has no file hashes")
        val stage = File(rootDirectory, ".stage-$version")
        stage.deleteRecursively()
        require(stage.mkdirs()) { "Could not create UI bundle staging directory" }
        try {
            for (name in UiBundleIntegrity.allowedAssetNames()) {
                val bytes = appContext.assets.open("ui-bundle/$name").use { it.readBytes() }
                val hash = expected.optString(name)
                require(UiBundleIntegrity.matches(name, bytes, hash)) { "Bundled UI asset hash mismatch: $name" }
                File(stage, name).writeBytes(bytes)
            }
            File(stage, "manifest.json").writeText(manifest.toString(), Charsets.UTF_8)
            val target = File(rootDirectory, version)
            if (target.exists()) target.deleteRecursively()
            require(stage.renameTo(target)) { "Could not activate bundled UI version" }
            if (!activePointer.exists()) activePointer.writeText(version, Charsets.UTF_8)
        } catch (error: Exception) {
            stage.deleteRecursively()
            throw error
        }
        return activeIndexFile()
    }

    fun activeVersion(): String = activePointer.takeIf { it.isFile }?.readText(Charsets.UTF_8)?.trim().orEmpty()

    fun activeIndexFile(): File {
        val version = activeVersion()
        require(isValidVersion(version)) { "No active UI bundle version is selected" }
        val directory = File(rootDirectory, version)
        verifyDirectory(directory)
        return File(directory, "index.html")
    }

    fun activeFiles(): Map<String, ByteArray> {
        val index = activeIndexFile()
        val directory = index.parentFile ?: error("Active UI bundle directory is unavailable")
        return UiBundleIntegrity.allowedAssetNames().associateWith { name ->
            File(directory, name).readBytes()
        }
    }

    fun installBundle(version: String, files: Map<String, ByteArray>, expectedHashes: Map<String, String>): File {
        require(isValidVersion(version)) { "Invalid UI bundle version" }
        require(files.keys == UiBundleIntegrity.allowedAssetNames()) { "UI bundle must contain exactly index.html, styles.css and app.js" }
        require(expectedHashes.keys == UiBundleIntegrity.allowedAssetNames()) { "UI bundle hash manifest is incomplete" }
        rootDirectory.mkdirs()
        val stage = File(rootDirectory, ".stage-$version")
        stage.deleteRecursively()
        require(stage.mkdirs()) { "Could not create UI bundle staging directory" }
        try {
            files.forEach { (name, bytes) ->
                require(UiBundleIntegrity.matches(name, bytes, expectedHashes[name].orEmpty())) {
                    "UI bundle integrity check failed: $name"
                }
                File(stage, name).writeBytes(bytes)
            }
            val manifest = JSONObject().put("version", version)
            val hashes = JSONObject()
            expectedHashes.forEach { (name, hash) -> hashes.put(name, hash.lowercase()) }
            manifest.put("files", hashes)
            File(stage, "manifest.json").writeText(manifest.toString(), Charsets.UTF_8)
            verifyDirectory(stage)
            val oldVersion = activeVersion()
            val target = File(rootDirectory, version)
            if (target.exists()) target.deleteRecursively()
            require(stage.renameTo(target)) { "Could not activate new UI bundle" }
            if (oldVersion.isNotBlank() && oldVersion != version) previousPointer.writeText(oldVersion, Charsets.UTF_8)
            activePointer.writeText(version, Charsets.UTF_8)
            return activeIndexFile()
        } catch (error: Exception) {
            stage.deleteRecursively()
            throw error
        }
    }

    fun rollbackAfterPageLoadFailure(): File? {
        val previous = previousPointer.takeIf { it.isFile }?.readText(Charsets.UTF_8)?.trim().orEmpty()
        if (!isValidVersion(previous)) return null
        return try {
            val previousIndex = File(File(rootDirectory, previous), "index.html")
            verifyDirectory(previousIndex.parentFile ?: return null)
            activePointer.writeText(previous, Charsets.UTF_8)
            previousIndex
        } catch (_: Exception) {
            null
        }
    }

    private fun verifyDirectory(directory: File) {
        require(directory.isDirectory) { "Active UI bundle directory is missing" }
        val manifestFile = File(directory, "manifest.json")
        require(manifestFile.isFile) { "UI bundle manifest is missing" }
        val manifest = JSONObject(manifestFile.readText(Charsets.UTF_8))
        require(isValidVersion(manifest.optString("version"))) { "UI bundle manifest version is invalid" }
        val hashes = manifest.optJSONObject("files") ?: error("UI bundle file hashes are missing")
        for (name in UiBundleIntegrity.allowedAssetNames()) {
            val file = File(directory, name)
            require(file.isFile) { "UI bundle asset is missing: $name" }
            require(UiBundleIntegrity.matches(name, file.readBytes(), hashes.optString(name))) {
                "UI bundle integrity check failed: $name"
            }
        }
    }

    private fun isValidVersion(value: String): Boolean = value.matches(Regex("^[A-Za-z0-9._-]{1,64}$"))
}
